package org.json;import java.util.*;public class JSONObject{private final Map<String,Object> values=new HashMap<>();public JSONObject put(String k,Object v){values.put(k,v);return this;}public String optString(String k){Object v=values.get(k);return v==null?"":v.toString();}public long optLong(String k,long f){Object v=values.get(k);return v instanceof Number?((Number)v).longValue():f;}public boolean optBoolean(String k){Object v=values.get(k);return v instanceof Boolean?(Boolean)v:false;}}
